import java.util.*;

class Solution {
  private int[] tree;
  private boolean[] flipped;

  public long[] handleQuery(int[] nums1, int[] nums2, int[][] queries) {
    tree = new int[nums1.length * 4];
    flipped = new boolean[nums1.length * 4];
    build(1, 0, nums1.length - 1, nums1);
    long sum = 0;
    for (int value : nums2) sum += value;
    List<Long> answer = new ArrayList<>();
    for (int[] query : queries) {
      if (query[0] == 1) flip(1, 0, nums1.length - 1, query[1], query[2]);
      else if (query[0] == 2) sum += (long) query[1] * tree[1];
      else answer.add(sum);
    }
    long[] result = new long[answer.size()];
    for (int i = 0; i < result.length; i++) result[i] = answer.get(i);
    return result;
  }

  private void build(int node, int left, int right, int[] values) {
    if (left == right) {
      tree[node] = values[left];
      return;
    }
    int middle = (left + right) >>> 1;
    build(node * 2, left, middle, values);
    build(node * 2 + 1, middle + 1, right, values);
    tree[node] = tree[node * 2] + tree[node * 2 + 1];
  }

  private void apply(int node, int left, int right) {
    tree[node] = right - left + 1 - tree[node];
    flipped[node] = !flipped[node];
  }

  private void push(int node, int left, int right) {
    if (!flipped[node] || left == right) return;
    int middle = (left + right) >>> 1;
    apply(node * 2, left, middle);
    apply(node * 2 + 1, middle + 1, right);
    flipped[node] = false;
  }

  private void flip(int node, int left, int right, int queryLeft, int queryRight) {
    if (queryLeft <= left && right <= queryRight) {
      apply(node, left, right);
      return;
    }
    push(node, left, right);
    int middle = (left + right) >>> 1;
    if (queryLeft <= middle) flip(node * 2, left, middle, queryLeft, queryRight);
    if (queryRight > middle) flip(node * 2 + 1, middle + 1, right, queryLeft, queryRight);
    tree[node] = tree[node * 2] + tree[node * 2 + 1];
  }
}
